Ltac solve_load_zsh :=
  match goal with
  | |- context [ov_read_bytes ?segs ?mc ?a 1%nat] =>
      let E := addr_expr a in
      lazymatch E with
      | sh8 ?x =>
          lazymatch goal with MU : munch ?W ?m0 mc |- _ =>
            match goal with ZS : zsh m0 ?A ?n |- _ =>
              (lazymatch goal with
               | _ : 2147450880 <= sh8 x /\ _ |- _ => idtac
               | _ => pose proof (sh8_bound47 x ltac:(lia))
               end);
              replace (ov_read_bytes segs mc a 1%nat) with (Some [b8 0])
                by (symmetry; exact (zsh_rd m0 mc W A n x ZS MU ltac:(outside_tac) ltac:(lia) ltac:(lia)))
            end
          end
      end
  end; load_post.
(* [comment removed for export] *)
Ltac solve_load ::= first [ solve_load_base | solve_load_zsh ].
Ltac print_hyps ::=
  try (match goal with H : ?T |- _ =>
         lazymatch T with
         | boxP ?P => idtac "  " H ": BOX" P
         | rw_cells _ _ _ _ => idtac "  " H ":" T
         | ro_cells _ _ _ _ => idtac "  " H ":" T
         | @eq Z _ _ => idtac "  " H ":" T
         | Z.lt _ _ => idtac "  " H ":" T
         | Z.le _ _ => idtac "  " H ":" T
         | not _ => idtac "  " H ":" T
         | _ /\ _ => idtac "  " H ":" T
         | _ \/ _ => idtac "  " H ":" T
         | munch _ _ _ => idtac "  " H ":" T
         | stk _ _ _ _ => idtac "  " H ":" T
         | _ => fail
         end; fail end).
